main.*:
{{#if:{{str endswith|{{{1}}}|%}} <!--(i.e. if {{{1}}} is a percentage)-->
 | [[Template:{{{2}}}|<span style="font-size:{{{1}}};">{{{3|{{{2}}}}}}</span>]]
 | [[Template:{{{1}}}|{{{2|{{{1}}}}}}]]
}}<noinclude>
{{Documentation}}
</noinclude>

{{{1}}}{{{{{|safesubst:}}}#ifeq:{{{sup}}}|yes
 |<sup>
}}{{{{{|safesubst:}}}#switch:{{{{{|safesubst:}}}#expr:abs({{{1}}}) mod 100}}
  |11|12|13=th
  |{{{{{|safesubst:}}}#switch:{{{{{|safesubst:}}}#expr:abs{{{1}}} mod 10}}
   |1=st
   |2={{{{{|safesubst:}}}#ifeq:{{{2|}}}|d|d|nd}}
   |3={{{{{|safesubst:}}}#ifeq:{{{2|}}}|d|d|rd}}
   |th
  }}
 }}{{{{{|safesubst:}}}#ifeq:{{{sup}}}|yes
 |</sup>
}}<noinclude>
{{documentation}}
</noinclude>

{{#switch: {{lc:{{{1|center}}}}}
|left = <div style="float: left;">{{{2}}}</div>
|right = <div style="float: right;">{{{2}}}</div>
|center = {{center|{{{2}}} }}
|#default = Error in [[Template:Align]]: the alignment setting "{{{1}}}" is invalid.
}}<noinclude>
{{documentation}}
</noinclude>

